"""
Loom Document Generator - Maintains REQUIREMENTS.md and TEST_SPEC.md
"""

import re
from pathlib import Path
from datetime import datetime, timezone
from typing import List, Dict, Optional, Tuple, Set

from .store import LoomStore, Requirement
from .testspec import TestSpec, TestSpecStore


# M-fix-A — strip the auto-generated timestamp line before comparing
# old vs new content. Same input → same bytes modulo this line, so a
# regeneration that only changes the timestamp should be a no-op
# write (preserves mtime, keeps `git status` clean).
_TIMESTAMP_LINE_RE = re.compile(
    r"^\*Auto-generated by Loom.*?\*$",
    re.MULTILINE,
)


def _normalize_for_compare(content: str) -> str:
    """Return content with the auto-generated timestamp line removed
    so byte-equal content (modulo regeneration time) compares equal."""
    return _TIMESTAMP_LINE_RE.sub("", content)


def _write_doc_if_changed(path: Path, content: str) -> bool:
    """Write ``content`` to ``path`` only if the content (minus the
    auto-generated timestamp line) differs from what's already on
    disk. Returns True when a write happened, False when skipped.

    Skipping the write preserves the file's mtime, which is what
    keeps ``git status`` clean after a no-op regeneration.
    """
    if path.exists():
        try:
            existing = path.read_text(encoding="utf-8")
        except OSError:
            existing = None
        if existing is not None and (
            _normalize_for_compare(existing) == _normalize_for_compare(content)
        ):
            return False
    path.write_text(content, encoding="utf-8")
    return True


def _format_spec_block(store: LoomStore, req_id: str, superseded_req_ids: Set[str]) -> List[str]:
    """Format the Specifications section under a requirement, with each spec's implementations."""
    specs = store.get_specifications_for_requirement(req_id)
    active_specs = [s for s in specs if not s.superseded_at]

    lines = []
    if active_specs:
        lines.append(f"- **Specifications ({len(active_specs)}):**")
        for spec in active_specs:
            lines.append(f"  - `{spec.id}` [{spec.status}] {spec.description[:80]}")
            spec_impls = store.get_implementations_for_specification(spec.id)
            if spec_impls:
                for impl in spec_impls:
                    lines.append(f"    - `{impl.file}` (lines {impl.lines})")
            else:
                lines.append(f"    - *No implementation linked*")
    else:
        lines.append("- **Specifications:** *None yet*")

    # Show direct (non-spec) implementation links as a fallback/legacy section
    direct_impls = [
        i for i in store.get_implementations_for_requirement(req_id)
        if not (i.satisfies_specs or [])
    ]
    if direct_impls:
        lines.append("- **Direct implementation links (consider adding specs):**")
        for impl in direct_impls:
            loc = f"`{impl.file}` (lines {impl.lines})"
            drifted = any(
                s["req_id"] in superseded_req_ids
                for s in impl.satisfies
                if s["req_id"] == req_id
            )
            if drifted:
                lines.append(f"  - {loc} — **drift detected**")
            else:
                lines.append(f"  - {loc}")

    return lines


def _format_impl_links(store: LoomStore, req_id: str, superseded_req_ids: Set[str]) -> List[str]:
    """Legacy flat format (kept for tests). Prefer _format_spec_block."""
    impls = store.get_implementations_for_requirement(req_id)
    if not impls:
        return ["- **Implementations:** *None yet*"]

    lines = ["- **Implementations:**"]
    for impl in impls:
        loc = f"`{impl.file}` (lines {impl.lines})"
        drifted = any(
            s["req_id"] in superseded_req_ids
            for s in impl.satisfies
            if s["req_id"] == req_id
        )
        if drifted:
            lines.append(f"  - {loc} — **drift detected**")
        else:
            lines.append(f"  - {loc}")
    return lines


def _format_link_chain(store: LoomStore, link_ids: List[str], *, value_chars: int = 80, rationale_chars: int = 80) -> List[str]:
    """Render a "Builds on:" entry per linked req (M11.2).

    Each line shows ``REQ-id`` plus the parent's value (truncated)
    plus the parent's rationale (truncated, italicized) when present.
    Returns a list of markdown lines (no leading/trailing blanks).
    """
    if not link_ids:
        return []
    out: List[str] = []
    for lid in link_ids:
        parent = store.get_requirement(lid)
        if parent is None:
            out.append(f"- `{lid}` *(missing — was the link target deleted?)*")
            continue
        value = parent.value
        if len(value) > value_chars:
            value = value[:value_chars - 1].rstrip() + "…"
        line = f"- `{parent.id}` — {value}"
        if parent.rationale:
            r = parent.rationale
            if len(r) > rationale_chars:
                r = r[:rationale_chars - 1].rstrip() + "…"
            line += f"\n  *Rationale: {r}*"
        out.append(line)
    return out


